import { createRouteBuilder } from '@cossackframework/core/routes';

const route = createRouteBuilder({ article: '/articles/:slug', files: '/files/:path{.+}' } as const);
const article: string = route('article', { slug: 'hello world' });
const files: string = route('files', { path: ['reports', 'October 2026.csv'] });
if (article !== '/articles/hello%20world') throw new Error('Article URL was not encoded');
if (files !== '/files/reports/October%202026.csv') throw new Error('Catch-all URL was not encoded');

import { startDevelopmentTrace } from '@cossackframework/core/devtools';
const check = (condition: boolean, message: string) => { if (!condition) throw new Error(message); };

// In a Vite development realm, capture is available; elsewhere the installed
// package must fail closed with the documented error instead of recording data.
let trace: ReturnType<typeof startDevelopmentTrace> | undefined;
let disabledCode: unknown;
try {
  trace = startDevelopmentTrace({ capacity: 16 });
} catch (error) {
  disabledCode = (error as { code?: unknown })?.code;
}

if (trace) {
  const snapshot = trace.snapshot();
  check(snapshot.schemaVersion === 1 && snapshot.collecting && snapshot.capacity === 16 && snapshot.events.length === 0, 'A new capture starts with an empty versioned bounded snapshot.');
  trace.stop();
  check(!trace.snapshot().collecting, 'Stopping capture marks its detached session as no longer collecting.');
} else {
  check(disabledCode === 'COSSACK_DEVTOOLS_DISABLED', 'Outside Vite development, capture fails closed with a stable diagnostic code.');
}

import { defineUrlState, url } from '@cossackframework/core/url-state';

const filters = defineUrlState({
  search: url.string(),
  page: url.integer({ default: 1, min: 1 }),
  tags: url.array(url.string()),
});
const repeated = filters.read('/articles?page=2&page=3');
if (repeated.values.page !== 1 || repeated.issues[0]?.code !== 'repeated-scalar') {
  throw new Error('Repeated page values must use the default and report an issue');
}
const destination = filters.url('/articles?utm=a%20b&page=bad#results', {
  search: 'snow & books', page: 2, tags: ['a/b', 'typescript'],
});
if (!destination.startsWith('/articles?utm=a%20b&') || !destination.endsWith('#results')) {
  throw new Error('Unrelated query bytes and fragment must survive');
}
const result = filters.read(destination);
const page: number = result.values.page;
if (result.issues.length || page !== 2 || result.values.search !== 'snow & books' || result.values.tags[0] !== 'a/b') {
  throw new Error('Typed query values must round-trip');
}
if (filters.read(filters.url(destination, { page: undefined })).values.page !== 1) {
  throw new Error('Undefined must reset a query field');
}

import { input, isActionValidationError, type InputOf, type RawInputOf } from '@cossackframework/core/input';

const schema = input.object({
  title: input.string({ required: true, maxLength: 120 }),
  copies: input.number({ coerce: true, integer: true, min: 1 }),
  published: input.boolean({ coerce: true }),
  note: input.string().optional(),
});
const raw: RawInputOf<typeof schema> = { title: 'Guide', copies: '2', published: 'false' };
const parsed: InputOf<typeof schema> = await schema.parse(raw);
const copies: number = parsed.copies;
if (copies !== 2 || parsed.published !== false || Object.hasOwn(parsed, 'note') || raw.copies !== '2') {
  throw new Error('Parsing must normalize a copy and preserve absent optional fields');
}
let rejected = false;
try {
  await schema.parse({ ...raw, canEdit: true });
} catch (error) {
  if (!isActionValidationError(error) || error.fieldErrors.canEdit !== 'Unknown field.') throw error;
  rejected = true;
}
if (!rejected) throw new Error('Unknown fields must fail validation');
// @ts-expect-error Parsed numeric fields cannot be strings.
const invalid: InputOf<typeof schema> = { title: 'Guide', copies: '2', published: false };
void invalid;

import { input } from '@cossackframework/core/input';

const controller = new AbortController();
let entered!: () => void;
const started = new Promise<void>(resolve => { entered = resolve; });
let rejectIgnored!: (error: Error) => void;
const ignored = new Promise<boolean>((_resolve, reject) => { rejectIgnored = reject; });
const schema = input.string().refine(async (_value, { signal }) => {
  if (signal !== controller.signal) throw new Error('Refinement lost the caller signal');
  entered();
  return ignored;
}, 'Name is unavailable');
const result = schema.parse('guide', { signal: controller.signal }).then(
  () => { throw new Error('Cancelled validation must not return a value'); },
  error => {
    if (!(error instanceof DOMException) || error.name !== 'AbortError') throw error;
  },
);
await started;
controller.abort();
await result;
// A late failure from ignored work must stay observed after cancellation.
rejectIgnored(new Error('Ignored validator stopped late'));
await new Promise<void>(resolve => setTimeout(resolve, 0));

import { input, isActionValidationError, parseFormData } from '@cossackframework/core/input';

const schema = input.object({
  profile: input.object({ name: input.string({ required: true }) }),
  items: input.array(input.object({ count: input.number({ coerce: true, integer: true, min: 1 }) }), { minItems: 1, maxItems: 3 }),
});
const form = new FormData();
form.append('profile[name]', 'Tan');
form.append('items[][count]', '2');
const parsed = await schema.parse(parseFormData(form));
if (parsed.profile.name !== 'Tan' || parsed.items[0]?.count !== 2) {
  throw new Error('Nested forms must return typed values');
}
form.set('items[][count]', 'bad');
let invalid = false;
try {
  await schema.parse(parseFormData(form));
} catch (error) {
  if (!isActionValidationError(error)) throw error;
  const items = error.fieldErrors.items as Record<string, Record<string, unknown>>;
  if (items['0']?.count !== 'Expected a safe integer.') throw error;
  invalid = true;
}
if (!invalid) throw new Error('Invalid nested counts must produce a field error');
form.set('items[][count]', '2');
form.append('profile[canEdit]', 'true');
let forged = false;
try {
  await schema.parse(parseFormData(form));
} catch (error) {
  if (!isActionValidationError(error)) throw error;
  const profile = error.fieldErrors.profile as Record<string, unknown>;
  if (profile.canEdit !== 'Unknown field.') throw error;
  forged = true;
}
if (!forged) throw new Error('Form parsing must not authorize forged fields');

import { Cossack, Page, State, ClientState, Server, Client, html } from '@cossackframework/core';
import { input, type InputOf } from '@cossackframework/core/input';

const incrementInput = input.object({ amount: input.number({ integer: true, min: 1, max: 5 }) });

@Page({ transport: 'http' })
export default class ActionPage extends Cossack {
  @State() count = 0;
  @ClientState() failure = '';

  @Server({ input: incrementInput })
  async increment(data: InputOf<typeof incrementInput>): Promise<number> {
    const next = this.count + data.amount;
    if (!Number.isSafeInteger(next)) throw new Error('PRIVATE_GUIDE_ACTION');
    this.count = next;
    return this.count;
  }

  @Client()
  async submit(amount: number) {
    this.failure = '';
    try { await this.increment({ amount }); }
    catch (error) {
      this.failure = error instanceof Error && 'code' in error ? String(error.code) : 'Request failed';
    }
  }

  render() {
    return html`<main>
      <h1>Validated counter</h1>
      <output id="guide-count">${this.count}</output>
      <output id="guide-loading">${this.loading.increment || 0}</output>
      <p role="alert">${this.failure}</p>
      <button @click=${() => this.submit(1)}>Add one</button>
      <button @click=${() => this.submit(0)}>Reject invalid input</button>
    </main>`;
  }
}

import { Cossack, Page, ClientState, Client, html, server$ } from '@cossackframework/core';

@Page({ transport: 'http' })
export default class ResourcePage extends Cossack<{}, { Resources: 'record' }> {
  @ClientState() selected = 1;
  record = server$((id: number) => {
    if (id === 3) throw new Error('PRIVATE_GUIDE_RESOURCE');
    return { id, label: 'Record ' + id };
  }, { deps: () => [this.selected] as const, initial: { id: 0, label: '' } });

  @Client() choose(id: number) { this.selected = id; }
  @Client() async refresh() { await this.refresh$('record'); }

  render() {
    const status = this.resourceStatus$('record');
    return html`<main>
      <h1>Server resource</h1>
      <output id="guide-record">${status.hasValue ? status.value.label : 'No record'}</output>
      <output id="guide-resource-state">${status.state}</output>
      <p role="alert">${status.state === 'error' ? 'Record unavailable. Try another selection.' : ''}</p>
      <button @click=${() => this.choose(2)}>Select two</button>
      <button @click=${() => this.choose(3)}>Select failing record</button>
      <button @click=${() => this.choose(4)}>Select four</button>
      <button @click=${() => this.refresh()} ?disabled=${status.state === 'pending'}>Refresh record</button>
    </main>`;
  }
}

import { Cossack, Page, ClientState, Client, ClientTask, html, type TaskContext } from '@cossackframework/core';

@Page({ transport: 'http' })
export default class TaskPage extends Cossack {
  @ClientState() query = 'initial';
  @ClientState() result = '';
  @ClientState() ticks = 0;

  @ClientTask<TaskPage>({ track: ['query'] as const })
  async update(signal: AbortSignal, task: TaskContext<TaskPage>) {
    const query = this.query;
    // Simulate a legacy operation that ignores the abort signal.
    await new Promise<void>(resolve => setTimeout(resolve, query === 'slow' ? 100 : 0));
    task.commit({ result: query });
    if (signal.aborted) return;
    const timer = setInterval(() => task.commit({ ticks: this.ticks + 1 }), 40);
    return () => clearInterval(timer);
  }

  @Client() choose(query: string) { this.query = query; }

  render() {
    return html`<main>
      <h1>Owned task</h1>
      <output id="guide-task-result">${this.result}</output>
      <output id="guide-task-ticks">${this.ticks}</output>
      <button @click=${() => this.choose('slow')}>Slow query</button>
      <button @click=${() => this.choose('fast')}>Fast query</button>
      <a href="/">Leave example</a>
    </main>`;
  }
}

import { Cossack, Page, State, old, flashed } from '@cossackframework/core';
import { html } from '@cossackframework/renderer';

interface PublicForm {
  name: string;
  email: string;
  password: string;
  profile: { city: string };
}

@Page({ transport: 'http' })
export default class PublicFormPage extends Cossack {
  @State() name = '';
  @State() email = '';
  @State() city = '';
  @State() errors: Record<string, string> | null = null;
  @State() notice = '';

  async init() {
    this.name = old<string>('name') ?? '';
    this.email = old<string>('email') ?? '';
    this.city = old<string>('profile.city') ?? '';
    this.errors = flashed<Record<string, string>>('errors') ?? null;
    this.notice = flashed<string>('success') ?? '';
  }

  async post() {
    const { valid } = await this.c.getFormData<PublicForm>({
      rules: { email: { required: true, email: true, message: 'Enter a valid email.' } },
      flash: { input: ['name', 'email', 'profile.city'] },
    });
    if (!valid) return this.c.redirect('/guidance-old-input');
    // Process validated data here. Authorize any account or storage operation.
    return this.c.redirect('/guidance-old-input');
  }

  render() {
    return html`<main><h1>Public form fields</h1>
      <p role="alert">${this.errors?.email ?? ''}</p>
      <form method="post" action="/guidance-old-input" novalidate>
        <label>Name <input name="name" value=${this.name} /></label>
        <label>Email <input name="email" value=${this.email} /></label>
        <label>City <input name="profile[city]" value=${this.city} /></label>
        <label>Password <input type="password" name="password" /></label>
        <button type="submit">Submit</button>
      </form>
    </main>`;
  }
}

import { detectBrowserLocale } from '@cossackframework/core';

const supported = ['en', 'fr', 'es'];
const selected = detectBrowserLocale('fr-CA, fr;q=0.9, en;q=0.8', supported, 'en');
if (selected !== 'fr') throw new Error('The best supported language range should win');
const fallback = detectBrowserLocale('de-DE, de;q=0.9', supported, 'en');
if (fallback !== 'en') throw new Error('Unsupported languages should use the configured fallback');
const excluded = detectBrowserLocale('fr;q=0', supported, 'en');
if (excluded !== 'en') throw new Error('A q=0 language range must remain unacceptable');

import { replacePlaceholders, selectPluralForm } from '@cossackframework/core';

const template = 'У вас :count яблоко|У вас :count яблока|У вас :count яблок';
const selected = selectPluralForm(template, 2, 'ru');
const message = replacePlaceholders(selected, { count: 2 });
if (message !== 'У вас 2 яблока') throw new Error('Russian plural category or placeholder was incorrect');

import { input } from '@cossackframework/core/input';
import { createJobRuntime, defineJob, LocalJobAdapter, MemoryJobStore, TransientJobError } from '@cossackframework/core/jobs';
const adapter = new LocalJobAdapter();
let attempts = 0;
const runtime = createJobRuntime({ namespace: 'guide', adapter, store: new MemoryJobStore(), now: adapter.now,
  jobs: { receipt: defineJob({ schema: input.object({ value: input.string({ required: true }) }), retryDelaySeconds: 10,
    handle() { if (++attempts === 1) throw new TransientJobError(); },
  }) },
});
await runtime.dispatch('receipt', { value: 'test' }, { scope: { tenantId: 'tenant', actorId: 'actor' }, idempotencyKey: 'receipt-1' });
const envelope = adapter.snapshot()[0]!.envelope;
if ((await adapter.drain(runtime))[0]?.status !== 'retry') throw Error('Transient failures must retry');
if ((await runtime.consume(envelope)).status !== 'retry' || attempts !== 1) throw Error('A duplicate cannot bypass backoff');
adapter.advance(10);
if ((await adapter.drain(runtime))[0]?.status !== 'completed') throw Error('Retry should complete after backoff');
if ((await runtime.consume(envelope)).status !== 'duplicate' || Number(attempts) !== 2) throw Error('Completed keys must not repeat');
// This adapter and store are process-only fixtures, not durable production storage.

import { input } from '@cossackframework/core/input';
import { createJobRuntime, defineJob, LocalJobAdapter, MemoryJobStore } from '@cossackframework/core/jobs';
import { createScheduleRuntime } from '@cossackframework/core/schedules';
const adapter = new LocalJobAdapter(); let effects = 0;
const jobs = createJobRuntime({ namespace: 'guide', adapter, store: new MemoryJobStore(), now: adapter.now,
  jobs: { report: defineJob({ schema: input.object({ title: input.string({ required: true }) }), handle() { effects++; } }) },
});
const schedules = createScheduleRuntime({ dispatcher: jobs, schedules: [{
  name: 'report', cron: '0 9 * * MON-FRI', job: 'report', payload: { title: 'PRIVATE_PAYLOAD' }, scope: { tenantId: 'PRIVATE_TENANT' },
}] as const });
const scheduledTime = Date.UTC(2026, 9, 5, 9);
await schedules.runOnce('report', { scheduledTime });
await schedules.scheduled({ cron: '0 9 * * MON-FRI', scheduledTime });
await adapter.drain(jobs);
if (Number(effects) !== 1) throw Error('One occurrence must share the jobs duplicate ledger');
if (JSON.stringify(schedules.list()).includes('PRIVATE_')) throw Error('Schedule inspection must omit payload/scope');

import { input } from '@cossackframework/core/input';
import { createNotificationRuntime, defineNotificationTemplate, notificationHtml, MemoryNotificationStore } from '@cossackframework/core/notifications';
let enabled = true; const pending: string[] = [];
const runtime = createNotificationRuntime({ namespace: 'guide', store: new MemoryNotificationStore(),
  preferences: () => enabled, dispatch: async id => { pending.push(id); },
  templates: { welcome: defineNotificationTemplate({ schema: input.object({ name: input.string({ required: true }) }),
    render(data) { return { subject: 'Welcome', text: data.name, html: notificationHtml`<p>${data.name}</p>` }; },
  }) },
});
const owner = { tenantId: 'tenant', userId: 'owner' };
const preview = await runtime.preview('welcome', { name: '<script>' });
if (preview.html !== '<p>&lt;script&gt;</p>' || pending.length !== 0) throw Error('Preview must escape without dispatch');
const first = await runtime.enqueue('welcome', { name: 'Ada' }, { channel: 'in-app', recipient: owner, idempotencyKey: 'welcome-1' });
await runtime.deliver(first.id!);
if ((await runtime.list({ tenantId: 'other', userId: 'owner' })).length !== 0) throw Error('Tenant inboxes must be isolated');
if (await runtime.setRead(first.id!, { tenantId: 'tenant', userId: 'another' }, true)) throw Error('Another user cannot mark read');
if (!await runtime.setRead(first.id!, owner, true) || !(await runtime.list(owner))[0]?.read) throw Error('Owner read state must persist');
const second = await runtime.enqueue('welcome', { name: 'Grace' }, { channel: 'in-app', recipient: owner, idempotencyKey: 'welcome-2' });
enabled = false;
if ((await runtime.deliver(second.id!)).code !== 'NOTIFICATION_PREFERENCE_DISABLED') throw Error('Delivery must recheck preferences');
if ((await runtime.list(owner)).length !== 1) throw Error('Suppressed delivery must not enter inbox');

import { Cossack, State, Store, ClientState, ClientStore, Computed, createStore, connectStore } from '@cossackframework/core';
class Basket extends Cossack {
 @State() count = 1;
 @Store() basket = { rows: [{ quantity: 2 }] };
 @ClientState() expanded = false;
 @ClientStore() draft = { note: '' };
 @Computed() get total(): number { return this.count + this.basket.rows.reduce((sum,row)=>sum+row.quantity,0); }
}
const source = createStore<number>(1);
const target = { count: 0 };
const seen: number[] = [];
const stop = source.subscribe(value=>seen.push(value));
const disconnect = connectStore(source,target,'count');
source.update(value=>value+1);source.set(2);
if(target.count!==2 || seen.join(',')!=='1,2')throw new Error('Subscriptions or equality suppression failed');
stop();disconnect();source.set(3);
if(target.count!==2 || seen.length!==2)throw new Error('Subscription cleanup failed');
export type BasketState = Pick<Basket,'count'|'basket'|'total'>;

import { Service, ServiceScope, DIContainer } from '@cossackframework/core';
@Service() class DraftService { note = ''; }
const first = new ServiceScope(undefined,[DraftService],{ownerRouteId:'first'});
const second = new ServiceScope(undefined,[DraftService],{ownerRouteId:'second'});
first.resolve(DraftService).note='private-first';
if(second.resolve(DraftService).note!=='')throw new Error('Scopes leaked state');
const child = new ServiceScope(first);
if(child.resolve(DraftService)!==first.resolve(DraftService))throw new Error('Parent declaration was not inherited');
const shadow = new ServiceScope(first,[DraftService]);
if(shadow.resolve(DraftService)===first.resolve(DraftService))throw new Error('Nested declaration did not shadow');
const container = new DIContainer();
if(container.resolve(DraftService)!==container.resolve(DraftService))throw new Error('Container singleton failed');
container.clear();
await first.disposeAsync();await second.disposeAsync();

guides.markdown:
@Optimistic('actionName') marks the synchronous browser handler associated with an inbound @Server action. Use optimistic(this).increment, append or remove inside that handler. Typed operations record edits for rebasing; do not replay arbitrary application handlers after a reply. Keep authoritative writes in the server action and make retryable mutations idempotent. Never await or perform I/O inside the optimistic handler.

The client reconciles authoritative replies and overlapping edits. A rejected call and an uncertain result are different: isUncertainRpcError identifies timeout, cancellation, disconnect and response failures that cannot establish whether the server write finished. Refresh authoritative state or inspect an application-owned receipt before resubmitting. Cancellation is not rollback. A public State field cannot establish authorization.

The typed definition demonstrates the compiled component contract. The executed assertions check uncertainty classification only; Node execution does not run the transformed proxy or prove optimistic UI behavior. Use a generated application for overlapping requests and rollback/rebase acceptance.

