import { rpc$,RpcError } from '@cossackframework/core';
import { evaluateTransportCapability, describeRuntimeCapabilities } from '@cossackframework/core/runtime-capabilities';
export async function consumeProxy(action:()=>AsyncGenerator<number,number,void>):Promise<number>{
 const call=rpc$(action);const values:number[]=[];
 for await(const value of call)values.push(value);
 return await call;
}
let code='';try{rpc$((async function*(){yield 1;return 2;})());}catch(error){if(error instanceof RpcError)code=error.code;else throw error;}
if(code!=='COSSACK_RPC_CALL_REQUIRED')throw new Error('A plain generator was misrepresented as a proxy');
if(evaluateTransportCapability('cloudflare','durable-object',{}).status!=='missing-binding')throw new Error('Native binding must be explicit');
if(describeRuntimeCapabilities('node',{}).durableState.status==='available')throw new Error('Process realtime is not durable');

import { createFormController, createFormBindings } from '@cossackframework/core';
import { input } from '@cossackframework/core/input';
const schema=input.object({name:input.string({minLength:1})});
const form=createFormController(schema,{name:''});
const bindings=createFormBindings(form,{id:'profile'});
const field=bindings.field('name');
if(field.label.for!==field.input.id || field.error.id!==field.input.id+'-error')throw new Error('Accessible associations failed');
let saves=0;
const invalid=await form.submit(async()=>{saves++;return 1;});
if(invalid.status!=='invalid'||saves!==0)throw new Error('Invalid input was submitted');
form.setFieldValue('name','Ada');
const submitted=await form.submit(async data=>{saves++;return data.name;});
if(submitted.status!=='submitted'||submitted.result!=='Ada'||Number(saves)!==1)throw new Error('Parsed submission failed');
form.reset();bindings.dispose();
if(form.getField('name').value!=='')throw new Error('Reset did not restore initial values');

import { Storage, StorageError, validateStorageKey, type StorageProvider } from '@cossackframework/core/storage';
let reads=0;
const provider:StorageProvider={name:'example-only',async put(){throw new Error('No upload configured');},async get(){reads++;return null;},async head(){return null;},async delete(){}};
const storage=new Storage<{userId:string}>({provider,authorize:({context,key})=>key.startsWith(context.userId+'/'),maxBytes:1024});
let code='';try{await storage.get({userId:'alice'},'bob/private.txt');}catch(error){if(error instanceof StorageError)code=error.code;else throw error;}
if(code!=='COSSACK_STORAGE_FORBIDDEN'||reads!==0)throw new Error('Unauthorized provider access');
if(await storage.get({userId:'alice'},'alice/readme.txt')!==null||Number(reads)!==1)throw new Error('Authorized read was not delegated');
let rejected=false;try{validateStorageKey('../secret');}catch(error){rejected=error instanceof StorageError;}
if(!rejected)throw new Error('Traversal key was accepted');

import { Image, imageDiagnostics } from '@cossackframework/core';
const props={src:'/images/avatar.png',width:64,height:64,alt:'Profile portrait',quality:80};
const diagnostics=imageDiagnostics(props,{provider:'none'});
if(!diagnostics.some(item=>item.code==='COSSACK_IMAGE_TRANSFORM_UNAVAILABLE'))throw new Error('Missing transform warning');
if(!imageDiagnostics({...props,width:0}).some(item=>item.severity==='error'))throw new Error('Invalid dimension accepted');
const template=Image({src:props.src,width:64,height:64,alt:props.alt});
if(!template)throw new Error('Image did not produce a template');

import { defineWorkflow,createWorkflowClient,createLocalWorkflowProvider } from '@cossackframework/core/workflows';
import { input } from '@cossackframework/core/input';
const events={approved:input.object({approved:input.boolean()})};
const definition=defineWorkflow({name:'local-approval',version:1,schema:input.object({reference:input.string()}),events,async run(_input,{step}){const event=await step.waitForEvent('approval','approved',{timeout:1000});return event.approved;}});
const provider=createLocalWorkflowProvider(definition,{env:undefined});
const client=createWorkflowClient(definition,provider,{namespace:'guide'});
const identity=await client.invoke({reference:'one'},{key:'one',scope:{actorId:'trusted-example'}});
await client.sendEvent(identity,'approved',{approved:true});
